import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, invoiceTotals, addLine, removeLine } from '../src/invoices.js';

test('createInvoice creates an invoice with enriched lines', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'STICKER', qty: 5 },
    ],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-001');
  assert.equal(result.value.issueDate, '2025-02-15');
  assert.equal(result.value.status, 'draft');
  assert.equal(result.value.lines.length, 2);

  const line1 = result.value.lines[0];
  assert.equal(line1.sku, 'DEV-HOUR');
  assert.equal(line1.name, 'Development (hour)');
  assert.equal(line1.qty, 10);
  assert.equal(line1.unitPrice, 9500);
  assert.equal(line1.vatRate, 21);

  const line2 = result.value.lines[1];
  assert.equal(line2.sku, 'STICKER');
  assert.equal(line2.name, 'Sticker sheet');
  assert.equal(line2.qty, 5);
  assert.equal(line2.unitPrice, 50);
  assert.equal(line2.vatRate, 21);
});

test('createInvoice reports unknown customer', () => {
  const result = createInvoice({
    customerId: 'C-999',
    issueDate: '2025-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.deepEqual(result, { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('createInvoice validates date format', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: 'not-a-date',
      lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    }),
    { ok: false, error: 'DATE_INVALID' }
  );

  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2025/02/15',
      lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    }),
    { ok: false, error: 'DATE_INVALID' }
  );

  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '02-15-2025',
      lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    }),
    { ok: false, error: 'DATE_INVALID' }
  );
});

test('createInvoice rejects invalid dates', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2025-02-30',
      lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    }),
    { ok: false, error: 'DATE_INVALID' }
  );

  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2025-13-01',
      lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    }),
    { ok: false, error: 'DATE_INVALID' }
  );
});

test('createInvoice requires at least one line', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2025-02-15',
      lines: [],
    }),
    { ok: false, error: 'NO_LINES' }
  );

  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2025-02-15',
      lines: null,
    }),
    { ok: false, error: 'NO_LINES' }
  );

  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2025-02-15',
      lines: undefined,
    }),
    { ok: false, error: 'NO_LINES' }
  );
});

test('createInvoice validates qty is a positive integer', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2025-02-15',
      lines: [{ sku: 'DEV-HOUR', qty: 0 }],
    }),
    { ok: false, error: 'QTY_INVALID' }
  );

  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2025-02-15',
      lines: [{ sku: 'DEV-HOUR', qty: -5 }],
    }),
    { ok: false, error: 'QTY_INVALID' }
  );

  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2025-02-15',
      lines: [{ sku: 'DEV-HOUR', qty: 1.5 }],
    }),
    { ok: false, error: 'QTY_INVALID' }
  );

  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2025-02-15',
      lines: [{ sku: 'DEV-HOUR', qty: 'ten' }],
    }),
    { ok: false, error: 'QTY_INVALID' }
  );
});

test('createInvoice reports unknown SKU', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2025-02-15',
      lines: [{ sku: 'UNKNOWN-SKU', qty: 1 }],
    }),
    { ok: false, error: 'UNKNOWN_SKU' }
  );
});

test('createInvoice does not mutate input', () => {
  const input = {
    customerId: 'C-001',
    issueDate: '2025-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  };
  const inputCopy = JSON.parse(JSON.stringify(input));

  createInvoice(input);

  assert.deepEqual(input, inputCopy);
});

test('createInvoice handles products with different VAT rates', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 1 }, // 21% VAT
      { sku: 'PRINT-A4', qty: 1 }, // 9% VAT
      { sku: 'WORKSHOP-DAY', qty: 1 }, // 0% VAT
    ],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].vatRate, 21);
  assert.equal(result.value.lines[1].vatRate, 9);
  assert.equal(result.value.lines[2].vatRate, 0);
});

test('createInvoice with valid leap year date', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-29',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.issueDate, '2024-02-29');
});

test('createInvoice rejects invalid leap year date', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2025-02-29',
      lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    }),
    { ok: false, error: 'DATE_INVALID' }
  );
});

test('createInvoice stops at first line error', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2025-02-15',
      lines: [
        { sku: 'DEV-HOUR', qty: 1 },
        { sku: 'DEV-HOUR', qty: -1 }, // Invalid
        { sku: 'UNKNOWN-SKU', qty: 1 }, // Also invalid, but we stop at the first one
      ],
    }),
    { ok: false, error: 'QTY_INVALID' }
  );
});

test('lineTotal calculates qty * unitPrice', () => {
  const line = { sku: 'DEV-HOUR', name: 'Development (hour)', qty: 10, unitPrice: 9500, vatRate: 21 };
  const result = lineTotal(line);
  assert.equal(result.ok, true);
  assert.equal(result.value, 95000);
});

test('lineTotal with qty of 1', () => {
  const line = { sku: 'STICKER', name: 'Sticker sheet', qty: 1, unitPrice: 50, vatRate: 21 };
  const result = lineTotal(line);
  assert.equal(result.ok, true);
  assert.equal(result.value, 50);
});

test('lineTotal with zero unitPrice', () => {
  const line = { sku: 'FREE', name: 'Free item', qty: 5, unitPrice: 0, vatRate: 0 };
  const result = lineTotal(line);
  assert.equal(result.ok, true);
  assert.equal(result.value, 0);
});

test('lineTotal requires positive quantity', () => {
  assert.deepEqual(
    lineTotal({ sku: 'DEV-HOUR', qty: 0, unitPrice: 9500, vatRate: 21 }),
    { ok: false, error: 'QTY_INVALID' }
  );

  assert.deepEqual(
    lineTotal({ sku: 'DEV-HOUR', qty: -1, unitPrice: 9500, vatRate: 21 }),
    { ok: false, error: 'QTY_INVALID' }
  );

  assert.deepEqual(
    lineTotal({ sku: 'DEV-HOUR', qty: 1.5, unitPrice: 9500, vatRate: 21 }),
    { ok: false, error: 'QTY_INVALID' }
  );
});

test('lineTotal requires non-negative integer unitPrice', () => {
  assert.deepEqual(
    lineTotal({ sku: 'DEV-HOUR', qty: 1, unitPrice: -100, vatRate: 21 }),
    { ok: false, error: 'LINE_INVALID' }
  );

  assert.deepEqual(
    lineTotal({ sku: 'DEV-HOUR', qty: 1, unitPrice: 95.5, vatRate: 21 }),
    { ok: false, error: 'LINE_INVALID' }
  );
});

test('lineTotal rejects non-object input', () => {
  assert.deepEqual(lineTotal(null), { ok: false, error: 'LINE_INVALID' });
  assert.deepEqual(lineTotal(undefined), { ok: false, error: 'LINE_INVALID' });
  assert.deepEqual(lineTotal('not an object'), { ok: false, error: 'LINE_INVALID' });
});

test('invoiceTotals calculates subtotal from all lines', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'STICKER', qty: 5 },
    ],
  });

  assert.equal(result.ok, true);
  const totalsResult = invoiceTotals(result.value);
  assert.equal(totalsResult.ok, true);
  assert.equal(totalsResult.value.subtotal, 10 * 9500 + 5 * 50);
  assert.equal(totalsResult.value.total, 10 * 9500 + 5 * 50);
});

test('invoiceTotals with single line', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert.equal(result.ok, true);
  const totalsResult = invoiceTotals(result.value);
  assert.equal(totalsResult.ok, true);
  assert.equal(totalsResult.value.subtotal, 5 * 9500);
  assert.equal(totalsResult.value.total, 5 * 9500);
});

test('invoiceTotals returns subtotal equal to total', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.equal(result.ok, true);
  const totalsResult = invoiceTotals(result.value);
  assert.equal(totalsResult.ok, true);
  assert.equal(totalsResult.value.subtotal, totalsResult.value.total);
});

test('invoiceTotals rejects non-object invoice', () => {
  assert.deepEqual(invoiceTotals(null), { ok: false, error: 'INVOICE_INVALID' });
  assert.deepEqual(invoiceTotals(undefined), { ok: false, error: 'INVOICE_INVALID' });
  assert.deepEqual(invoiceTotals('not an object'), { ok: false, error: 'INVOICE_INVALID' });
});

test('invoiceTotals requires non-empty lines', () => {
  assert.deepEqual(
    invoiceTotals({ customerId: 'C-001', issueDate: '2025-02-15', status: 'draft' }),
    { ok: false, error: 'NO_LINES' }
  );

  assert.deepEqual(
    invoiceTotals({ customerId: 'C-001', issueDate: '2025-02-15', status: 'draft', lines: [] }),
    { ok: false, error: 'NO_LINES' }
  );
});

test('invoiceTotals reports invalid line', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2025-02-15',
    status: 'draft',
    lines: [
      { sku: 'DEV-HOUR', name: 'Development', qty: -1, unitPrice: 9500, vatRate: 21 },
    ],
  };

  assert.deepEqual(invoiceTotals(invoice), { ok: false, error: 'QTY_INVALID' });
});

test('invoiceTotals with large numbers', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-15',
    lines: [
      { sku: 'BRAND-BOOK', qty: 100 },
    ],
  });

  assert.equal(result.ok, true);
  const totalsResult = invoiceTotals(result.value);
  assert.equal(totalsResult.ok, true);
  assert.equal(totalsResult.value.subtotal, 100 * 245000);
});

test('invoiceTotals does not mutate the invoice', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.equal(result.ok, true);
  const invoice = result.value;
  const invoiceCopy = JSON.parse(JSON.stringify(invoice));

  invoiceTotals(invoice);

  assert.deepEqual(invoice, invoiceCopy);
});

test('addLine adds a new line to an invoice', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert.equal(result.ok, true);
  const invoiceWithNewLine = addLine(result.value, { sku: 'STICKER', qty: 10 });

  assert.equal(invoiceWithNewLine.ok, true);
  assert.equal(invoiceWithNewLine.value.lines.length, 2);
  assert.equal(invoiceWithNewLine.value.lines[0].sku, 'DEV-HOUR');
  assert.equal(invoiceWithNewLine.value.lines[1].sku, 'STICKER');
  assert.equal(invoiceWithNewLine.value.lines[1].qty, 10);
  assert.equal(invoiceWithNewLine.value.lines[1].name, 'Sticker sheet');
  assert.equal(invoiceWithNewLine.value.lines[1].unitPrice, 50);
});

test('addLine increases qty if SKU already exists', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert.equal(result.ok, true);
  const invoiceWithMoreQty = addLine(result.value, { sku: 'DEV-HOUR', qty: 3 });

  assert.equal(invoiceWithMoreQty.ok, true);
  assert.equal(invoiceWithMoreQty.value.lines.length, 1);
  assert.equal(invoiceWithMoreQty.value.lines[0].qty, 8);
  assert.equal(invoiceWithMoreQty.value.lines[0].sku, 'DEV-HOUR');
});

test('addLine validates qty is positive integer', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.equal(result.ok, true);

  assert.deepEqual(addLine(result.value, { sku: 'STICKER', qty: 0 }), {
    ok: false,
    error: 'QTY_INVALID',
  });

  assert.deepEqual(addLine(result.value, { sku: 'STICKER', qty: -1 }), {
    ok: false,
    error: 'QTY_INVALID',
  });

  assert.deepEqual(addLine(result.value, { sku: 'STICKER', qty: 1.5 }), {
    ok: false,
    error: 'QTY_INVALID',
  });
});

test('addLine validates SKU exists', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.equal(result.ok, true);

  assert.deepEqual(addLine(result.value, { sku: 'UNKNOWN-SKU', qty: 1 }), {
    ok: false,
    error: 'UNKNOWN_SKU',
  });
});

test('addLine requires draft status', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.equal(result.ok, true);
  const invoice = result.value;

  // Try to add line to non-draft invoice
  const nonDraftInvoice = { ...invoice, status: 'sent' };

  assert.deepEqual(addLine(nonDraftInvoice, { sku: 'STICKER', qty: 1 }), {
    ok: false,
    error: 'NOT_DRAFT',
  });
});

test('addLine does not mutate the original invoice', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert.equal(result.ok, true);
  const invoice = result.value;
  const invoiceCopy = JSON.parse(JSON.stringify(invoice));

  addLine(invoice, { sku: 'STICKER', qty: 1 });

  assert.deepEqual(invoice, invoiceCopy);
});

test('addLine preserves other invoice properties', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.equal(result.ok, true);
  const updated = addLine(result.value, { sku: 'STICKER', qty: 1 });

  assert.equal(updated.ok, true);
  assert.equal(updated.value.customerId, 'C-001');
  assert.equal(updated.value.issueDate, '2025-02-15');
  assert.equal(updated.value.status, 'draft');
});

test('removeLine removes a line from an invoice', () => {
